// Authoring artifact: writes candidates only. Rebuilding requires independent review.
import { promises as fs } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createHash } from 'node:crypto';
const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, '../../..');
const read = async relative => JSON.parse((await fs.readFile(path.join(root, relative), 'utf8')).replace(/^\uFEFF/, ''));
const inventory = await read('data/extracted/inventory.json');
const documents = new Map();
for (const item of inventory) {
  const document = await read(`data/extracted/${item.outputFile}`);
  const hash = createHash('sha256').update(await fs.readFile(path.join(root, 'artigos', item.file))).digest('hex');
  if (hash !== item.sha256 || hash !== document.sha256 || document.status !== 'ok') throw Error(`Fonte mudou: ${item.articleId}`);
  documents.set(item.articleId, document);
}
const ids = { rp:'article-39adb0cfa84e', sbd:'article-d4b0c4f9d75f', art:'article-94e7a19d8878', chip:'article-eca18e5843e2', agenda:'article-d0d500126a80', hci:'article-e13c3cb65c28', interact:'article-48bdcebcffc6' };
function source(key, pages, sections) {
  const doc = documents.get(ids[key]);
  return { file:doc.file, title:doc.title, pages, sections, evidence:pages.map(page => {
    const text = doc.pages.find(item => item.page === page)?.text;
    if (!text) throw Error(`Página ausente ${key}:${page}`);
    return text;
  }) };
}
const cards = [];
function direct(question, answer, pages, sections) {
  cards.push({ id:`${ids.rp}-${String(cards.length+9).padStart(2,'0')}`, articleId:ids.rp, question, answer, source:source('rp',pages,sections), kind:'direct' });
}
function synthesis(question, answer, pages, sections, ...others) {
  cards.push({ id:`${ids.rp}-${String(cards.length+9).padStart(2,'0')}`, articleId:ids.rp, question, answer, source:source('rp',pages,sections), kind:'synthesis', relatedSources:others.map(([key,pages,sections]) => ({ articleId:ids[key], source:source(key,pages,sections) })) });
}

direct('Por que a existência de catálogos de padrões enganosos ainda não fornece, segundo Operationalizing, orientação suficiente para redesenhar daily quests ou fluxos de compras?',
'O artigo distingue [[identificar problemas ou oferecer orientação ampla]] de desenvolver e avaliar aplicações concretas de padrões benéficos. Propostas positivas podem permanecer conceituais, sem exemplos de implementação detalhados e empiricamente validados para mecânicas e interfaces específicas. Assim, um designer pode compreender a ideia de autonomia e continuar sem saber como redesenhar uma missão diária ou compra no aplicativo. A lacuna inclui avaliar os resultados tanto para o [[bem-estar do jogador quanto para os objetivos do desenvolvedor]]. O template busca tornar a discussão aplicável; sua apresentação não demonstra que essa lacuna empírica já tenha sido resolvida.',[2],['1 Introduction']);

direct('Que combinação de custo, escala e imitação ajuda Operationalizing a explicar a persistência de padrões enganosos mesmo quando já foram catalogados?',
'O texto aponta [[baixo custo de implementação, possibilidade de aplicação em escala e capacidade de capturar/manipular jogadores]]. Associa essa operação à exploração de vieses cognitivos e à indução de gastos de tempo e dinheiro que podem prejudicar o bem-estar. Também argumenta que títulos comercialmente bem-sucedidos funcionam como modelos para outros desenvolvedores, que reproduzem mecânicas e estratégias visando ganho financeiro e engajamento, por vezes sem compreender suas consequências. Trata-se da explicação apresentada pelo artigo para a persistência dessas práticas; a mera disponibilidade de um catálogo de danos não elimina os [[incentivos de produção e comercialização]].',[3,4],['2 How Deceptive Patterns in Digital Games Affects Players and Player-Experience']);

direct('Como Operationalizing distingue reconhecer padrões familiares de compreender suas consequências éticas, e por que a apresentação na interface importa?',
'Segundo o artigo, experiência individual e [[letramento digital sobre ética em jogos]] afetam a percepção das práticas. Jogadores conscientes podem reconhecê-las e evitar jogos que as utilizem, enquanto outros permanecem envolvidos sem compreender as consequências. Familiaridade também não basta: jogadores experientes podem reconhecer padrões como estratégias usuais de engajamento sem entender plenamente seus efeitos. O texto acrescenta que a frequência percebida e a forma de apresentação na UI influenciam a eficácia desses padrões. Portanto, [[reconhecimento, compreensão e experiência]] não são condições equivalentes, nem permitem prever uma resposta uniforme entre perfis.',[4,14],['2 How Deceptive Patterns in Digital Games Affects Players and Player-Experience','6.1 Players Perception on Radiant Patterns']);

direct('Que distinção entre bem-estar hedônico e eudaimônico sustenta a discussão de SDT em Operationalizing, e por que prazer não esgota a análise?',
'Na apresentação do artigo, perspectivas [[hedônicas]] definem bem-estar principalmente em termos de prazer e felicidade. Perspectivas [[eudaimônicas]] tratam-no como construto multidimensional que ultrapassa o prazer, envolvendo significado, autorrealização e busca de objetivos intrinsecamente valiosos. O texto aproxima essa segunda perspectiva da Teoria da Autodeterminação e das necessidades de autonomia, competência e vínculo. As perspectivas são descritas como sobrepostas, mas distintas. Assim, apreciar um momento de jogo não esgota a pergunta sobre as condições psicológicas que a experiência apoia; o enquadramento do artigo procura analisar [[necessidades básicas e funcionamento psicológico]], sem reduzir bem-estar a diversão imediata.',[4,5],['3 Well-Being Applied to Game Design']);

direct('Por que Operationalizing não permite interpretar mais tempo de jogo, isoladamente, como indicador simples de melhora ou piora do bem-estar?',
'A discussão condiciona a relação entre tempo e bem-estar às [[motivações subjacentes e ao suporte à satisfação das necessidades psicológicas]]. Quando autonomia, competência e vínculo são apoiados e o jogador está intrinsecamente motivado, a experiência pode ser avaliada de forma mais positiva; o texto associa maior tempo, nesse contexto, mais provavelmente a bem-estar. Necessidades frustradas e pressões externas, por outro lado, são relacionadas a funcionamento psicológico diminuído. A experiência do jogador aparece como fator moderador. Portanto, a quantidade de horas não substitui a análise de [[por que se joga e como a experiência é estruturada]], nem estabelece sozinha causalidade.',[4,5],['3 Well-Being Applied to Game Design']);

direct('Que dificuldades de verificabilidade e de trade-offs o artigo identifica nas expressões da definição original de Radiant Patterns?',
'O artigo considera expressões como [[preservar o bem-estar e prevenir experiências negativas]] amplas e abertas a interpretação individual, dificultando aplicação e avaliação consistentes. Acrescenta que a definição oferece pouca orientação para verificar empiricamente o suporte às necessidades ou resolver situações em que satisfazer uma dimensão afeta outra. A variedade emocional e os desafios inerentes ao jogo também impedem transformar toda experiência negativa em critério de falha. A exigência metodológica é passar de uma aspiração moral genérica para [[parâmetros operacionais verificáveis]], sem supor que nomear autonomia, competência e vínculo já forneça uma avaliação empírica.',[6],['4 Revisiting and Reshaping Game Radiant Patterns']);

direct('Como Operationalizing coloca os objetivos do desenvolvimento dentro de limites éticos, em vez de exigir que todo objetivo comercial ou de engajamento desapareça?',
'A definição refinada permite perseguir [[objetivos de desenvolvimento]], desde que o bem-estar básico não seja significativamente comprometido e que autonomia, competência e vínculo não diminuam por decisões prejudiciais. Ela fornece restrições preventivas diante de riscos previsíveis e padrões conhecidos de frustração das necessidades. O exemplo World Creation concretiza essa posição: a monetização pode se dirigir a melhorias opcionais, acesso à plataforma ou ofertas comunitárias adjacentes, mantendo o ato básico de criação separado de pressão financeira sobre funções centrais. Isso é uma [[orientação de design com limites]], não demonstração de que qualquer modelo comercial seja ético ou rentável.',[6,12],['4 Revisiting and Reshaping Game Radiant Patterns','5.2 Radiant Pattern Example']);

direct('O que a noção de padrão recorrente permite repetir e variar, segundo a fundamentação de Operationalizing, e por que isso não equivale a copiar uma receita idêntica?',
'O artigo recorre à ideia de um [[problema que reaparece e do núcleo de uma solução reutilizável]], capaz de ser empregado muitas vezes sem ser realizado exatamente do mesmo modo. No domínio dos jogos, apresenta padrões como descrições semiformais e interdependentes de partes recorrentes do design relacionadas ao gameplay. Essa base permite distinguir a identidade conceitual de uma solução de suas realizações particulares. Por isso, documentar um padrão não significa impor uma interface única: [[contexto, mecânica e forma de implementação]] precisam ser explicitados, e o próprio artigo pede cenários e estilos de jogo recomendados para a aplicação.',[7,8,9],['5 Crafting Radiance: A Guide to Propose Radiant Patterns','5.1 Radiant Pattern Structure']);

direct('Que função o campo Name exerce no template de Operationalizing e que características os autores recomendam para nomear um padrão?',
'O nome pode ser [[uma palavra ou uma expressão que descreva o conceito fundamental]] do padrão. A recomendação é estabelecer associação direta com uma experiência positiva para o jogador, escolhendo nomes que evoquem autonomia e senso de realização; o texto exemplifica com creation, free e evolution. Esse campo tem função de identificação e comunicação no conjunto documentado. Não substitui a descrição do problema, do contexto, da solução e dos efeitos sobre necessidades: um nome positivo não demonstra, por si só, que a implementação respeite os [[critérios preventivos de um Radiant Pattern]].',[9],['5.1 Radiant Pattern Structure','Name']);

direct('O que deve ser documentado em Problem no template de Operationalizing, e como isso evita apresentar uma mecânica sem justificar a situação à qual responde?',
'O campo [[Problem]] descreve a questão de game design que o padrão pretende enfrentar. Partindo da função dos padrões como soluções para situações recorrentes, o artigo situa esses problemas em aspectos que prejudicam o bem-estar ou deixam de satisfazer necessidades psicológicas básicas. A estrutura exige tornar visível o problema antes de apresentar a solução; na elaboração do template, os autores observam que padrões enganosos frequentemente são usados como respostas a situações de design e procuram alternativas mais éticas para esses objetivos. Assim, a documentação conecta [[necessidade de projeto, problema vivido e solução proposta]], sem converter uma mecânica isolada em justificativa suficiente.',[8,9],['5 Crafting Radiance: A Guide to Propose Radiant Patterns','5.1 Radiant Pattern Structure','Problem']);

direct('Por que Context precisa indicar cenários e estilos de jogo recomendados em Operationalizing, em vez de declarar um padrão universalmente benéfico?',
'O artigo afirma que um padrão [[não está presente em todos os jogos e seu contexto varia]]. Por isso, requer descrição detalhada dos cenários e estilos nos quais pode ser utilizado, respeitando suas características particulares. Essa delimitação integra a análise de como a solução responde ao problema naquela situação e de como sua aplicação inadequada pode produzir efeito contrário ao pretendido. A seção de limitações também reconhece diferenças entre perfis e experiências dos jogadores. Logo, o campo Context fornece [[condições de aplicação]], enquanto os resultados reais sobre jogadores ainda exigem avaliação; ele não é um selo de benefício garantido em qualquer jogo.',[8,9,14],['5 Crafting Radiance: A Guide to Propose Radiant Patterns','5.1 Radiant Pattern Structure','Context','6.1 Players Perception on Radiant Patterns']);

direct('Como o campo Proposed Solution deve ligar problema, mecânica e objetivos de desenvolvimento na documentação de um Radiant Pattern?',
'A solução proposta explica [[como o padrão enfrenta o problema recorrente no contexto identificado]]. Ela descreve a mecânica ou interação central e como sua implementação permite perseguir objetivos de desenvolvimento preservando o bem-estar básico do jogador. O processo de elaboração do template exige ir além de dizer que o padrão é positivo: deve-se explicar sua operação e, depois, como evita diminuir cada necessidade psicológica. Assim, Proposed Solution torna a alternativa de design discutível e aplicável, articulando [[problema, contexto e mecanismo]], mas a existência dessa descrição ainda não equivale a comprovar efeitos ou viabilidade comercial.',[8,9],['5 Crafting Radiance: A Guide to Propose Radiant Patterns','5.1 Radiant Pattern Structure','Proposed Solution']);

direct('Por que Operationalizing exige examinar autonomia, competência e vínculo individualmente, em vez de justificar um ganho psicológico agregado?',
'A estrutura pede uma [[exposição específica do impacto em cada necessidade básica]]. O texto insiste em explicar como o padrão promove ou apoia autonomia, competência e vínculo sem produzir efeito negativo, evitando que a realização de uma necessidade interfira na de outra. Essa exigência responde à dificuldade da definição inicial em orientar trade-offs. Portanto, uma justificativa genérica de que o padrão melhora o bem-estar não basta: a documentação deve identificar mecanismos e possíveis perdas por dimensão, tornando as escolhas [[rastreáveis e passíveis de crítica]], ainda que a descrição estrutural por si só não substitua estudos com jogadores.',[6,8,10],['4 Revisiting and Reshaping Game Radiant Patterns','5 Crafting Radiance: A Guide to Propose Radiant Patterns','5.1 Radiant Pattern Structure','Avoiding Decrease in Autonomy, Relatedness and Competence']);

direct('Qual problema de agência e expressão World Creation pretende enfrentar, e como o artigo associa mundos inertes a oportunidades de interação?',
'O exemplo parte de situações em que jogadores têm [[pouca agência, caminhos criativos ou canais de expressão significativa]] dentro de parâmetros predeterminados. O texto acrescenta que mundos inertes podem limitar a continuidade do jogo e interações sociais baseadas em experiências compartilhadas. A resposta proposta é permitir criar, personalizar, colaborar e compartilhar cenários mediante ferramentas e recursos acessíveis. A justificativa, portanto, envolve expressão e relações, e não apenas quantidade de conteúdo. World Creation é apresentado como [[exemplo documentado de uma mecânica]], cujos efeitos diretos no bem-estar não foram validados por avaliações com jogadores nesse trabalho.',[10,11,16],['5.2 Radiant Pattern Example','Problem','Proposed Solution','6.5 Study Limitations']);

direct('Em quais contextos World Creation é proposto e que condições de acesso à criação integram a solução apresentada?',
'O contexto descrito abrange jogos em que os jogadores [[interagem com sistemas do jogo e potencialmente entre si]], incluindo diferentes gêneros, como sandbox, plataformas e suítes criativas. A solução permite criar, personalizar e colaborar ou compartilhar cenários com ferramentas e recursos acessíveis. A continuação do texto esclarece que funções criativas centrais não devem depender de pagamento direto ou grind repetitivo excessivo. Assim, amplitude de gêneros não significa ausência de condições: o exemplo combina [[possibilidade de criação e acesso efetivo aos recursos fundamentais]], mantendo a aplicação condicionada às características do jogo.',[10,11],['5.2 Radiant Pattern Example','Context','Proposed Solution']);

direct('Que mecanismo de World Creation o artigo associa à autonomia e como essa justificativa vai além de simplesmente oferecer opções cosméticas?',
'Na documentação do exemplo, autonomia é apoiada pelo [[controle e liberdade sobre as próprias criações e sobre a interação com o mundo]]. O jogador pode personalizar seus ambientes e expressar decisões criativas. Essa descrição precisa ser lida com as advertências seguintes: impedir acesso a ferramentas fundamentais por pagamento ou grind excessivo restringe a capacidade de realizar a visão criativa. Portanto, a justificativa não é somente que existam escolhas visuais, mas que haja [[capacidade real de criar e controlar a expressão]]. Trata-se do mecanismo proposto pelos autores, não de um efeito medido em uma amostra de jogadores.',[11,12,16],['5.2 Radiant Pattern Example','Avoiding Decrease in Autonomy, Relatedness, and Competence','Watch For','6.5 Study Limitations']);

direct('Como aprender e dominar ferramentas em World Creation é relacionado à competência, e o que diferencia desafio criativo de impedimento imposto pela ferramenta?',
'O exemplo relaciona competência à oportunidade de [[aprender, dominar ferramentas, ser criativo e superar desafios de design]]. Criar e compartilhar conteúdo com sucesso pode produzir senso de realização. Já ferramentas mal desenhadas, com bugs, ausência de funções básicas ou documentação ruim fazem a pessoa sentir-se impedida por limitações do instrumento, em vez de por seu nível de habilidade. O ponto é oferecer condições para [[desenvolvimento de capacidade e expressão do domínio]], sem tomar a frustração causada por uma interface deficiente como desafio criativo desejável. Essa é a argumentação do padrão; seus efeitos diretos ainda requerem validação.',[11,12,16],['5.2 Radiant Pattern Example','Competence','Poor implementations or Obfuscated Tools','6.5 Study Limitations']);

direct('Que papel compartilhar, colaborar e jogar criações de outras pessoas ocupa na dimensão de vínculo de World Creation?',
'A documentação associa vínculo à possibilidade de [[compartilhar criações, colaborar e experimentar o trabalho de outros jogadores]]. Essas ações criam oportunidades de interação social e conexão por atividades criativas. Por isso, o padrão não se limita à produção individual de conteúdo: facilitar a conexão com a comunidade integra seu mecanismo proposto. A seção de falhas aponta que compartilhamento difícil, descoberta insuficiente e restrições arbitrárias podem negar fortemente essa dimensão. Logo, ter um editor de fases não basta para justificar suporte a vínculo se a circulação e a colaboração forem bloqueadas; é preciso analisar a [[estrutura efetiva de conexão]].',[11,12,13],['5.2 Radiant Pattern Example','Relatedness','Restrictive Sharing and Discovery Mechanisms','Facilitating Sharing and Community']);

direct('Quais funções centrais World Creation não deve condicionar a pagamento ou grind excessivo, e por que isso é tratado como risco psicológico previsível?',
'O artigo inclui [[ferramentas criativas fundamentais, elementos básicos e a capacidade principal de salvar e compartilhar criações]]. Condicioná-los a esforço repetitivo excessivo ou gasto financeiro é descrito como risco de frustração e exploração: restringe a liberdade de criar e faz o progresso parecer artificial ou impedido por fatores externos à habilidade. Não se trata de proibir toda progressão ou compra; a advertência protege o [[núcleo da atividade criativa]]. O juízo se refere à implementação discutida no exemplo e a critérios preventivos, não a uma avaliação empírica de todo modelo de monetização existente.',[12],['5.2 Radiant Pattern Example','Watch For','Implementations Failing to Meet RP Criteria']);

direct('Que espaço para monetização World Creation admite e como separa ofertas opcionais de pressão financeira sobre o núcleo criativo?',
'O texto propõe direcionar monetização a [[melhorias opcionais, acesso à plataforma ou ofertas comunitárias adjacentes]], preservando o ato básico de criação e seu vínculo com proficiência. Também admite peças extras e recompensas opcionais, desde que a capacidade central de criar e expressar-se não dependa de custos irrazoáveis ou grind excessivo. Essa distinção permite discutir objetivos de desenvolvimento dentro de limites preventivos. Não é uma autorização para qualquer compra rotulada como opcional: é necessário examinar se ela mantém [[ferramentas fundamentais, salvamento e compartilhamento]] separados da pressão financeira, sem alegar rentabilidade demonstrada.',[12,13,16],['5.2 Radiant Pattern Example','Watch For','Accessible Core Creative Suite','Optional Unlocks By Engaging Play','6.5 Study Limitations']);

direct('Por que bugs, documentação insuficiente e ausência de posicionamento preciso ou desfazer são falhas de World Creation relevantes para autonomia e competência?',
'Esses exemplos mostram uma implementação em que o jogador é limitado pela [[qualidade e pelas capacidades das ferramentas]], e não por seu domínio criativo. O artigo explica que interfaces mal desenhadas, defeituosas ou sem funções básicas comprometem o sentimento de competência, pois dificultam realizar ideias por razões externas à habilidade. A autonomia também diminui quando formas de expressão se tornam efetivamente impossíveis. A seção ensina que apenas disponibilizar um editor não resolve o problema: [[usabilidade, documentação e operações básicas]] fazem parte das condições pelas quais a proposta criativa pode cumprir seus critérios.',[12],['5.2 Radiant Pattern Example','Poor implementations or Obfuscated Tools']);

direct('Como restrições de compartilhamento e descoberta podem contrariar World Creation mesmo quando as ferramentas de criação funcionam?',
'O artigo descreve compartilhamento difícil, ausência de mecanismos de busca ou curadoria e [[restrições arbitrárias ao que ou quanto se pode compartilhar]]. Tais obstáculos podem negar a dimensão de vínculo, porque a motivação de muitos criadores inclui comunicar-se com a comunidade. Assim, a existência de ferramentas funcionais não resolve sozinha o problema de conexão: a circulação do trabalho e a descoberta de outras criações também estruturam a experiência. A implementação compatível enfatiza publicar, descobrir e jogar conteúdo comunitário de modo acessível e satisfatório, evitando [[isolar os criadores]] do ecossistema social que dá valor à criação.',[12,13],['5.2 Radiant Pattern Example','Restrictive Sharing and Discovery Mechanisms','Facilitating Sharing and Community']);

direct('Qual risco de scaffolding insuficiente aparece em World Creation e que apoios o texto sugere para ambientes de criação sofisticados?',
'Ambientes muito sofisticados podem [[sobrecarregar usuários]] quando não contam com tutoriais sólidos, liberação progressiva de recursos ou orientação explícita. Expor grande complexidade sem apoio pode gerar frustração recorrente e abandono, impedindo a competência que o padrão pretende apoiar. A advertência distingue dificuldade de criação de falta de condições para aprender a ferramenta. Na implementação compatível, recursos responsivos, feedback claro e tutoriais adequados integrados ao gameplay tornam o ambiente aprendível e utilizável. Assim, o suporte não precisa eliminar a complexidade criativa; deve oferecer [[condições para apropriação gradual e domínio]].',[12,13],['5.2 Radiant Pattern Example','Insufficient Scaffolding of Sophisticated Tools','Intuitive Design and Clear Feedback']);

direct('Como Accessible Core Creative Suite combina disponibilidade inicial de ferramentas com a possibilidade de oferecer peças extras?',
'A implementação compatível prevê [[um conjunto robusto de elementos e ferramentas centrais imediatamente disponível]]. O texto admite que algumas peças extras tenham uma barreira inicial, mas exige que a capacidade básica de criação e expressão permaneça desvinculada de grind irrazoável ou gastos monetários. A distinção não se faz pela mera presença de conteúdo desbloqueável: pergunta-se se o que está bloqueado é periférico ou essencial para realizar a atividade criativa. Essa organização procura apoiar autonomia e estabelecer uma base para desenvolver competência, sem afirmar que a [[distribuição particular de recursos]] já tenha sido validada com jogadores.',[12,13,16],['5.2 Radiant Pattern Example','Accessible Core Creative Suite','6.5 Study Limitations']);

direct('Que elementos de Intuitive Design and Clear Feedback são propostos para apoiar competência sem confundir orientação com eliminação do aprendizado?',
'A implementação descrita combina [[ferramentas amigáveis e responsivas, feedback claro e tutoriais adequados integrados ao gameplay]]. Sua finalidade é tornar os recursos aprendíveis e utilizáveis, dando ao jogador condições de agir e reduzindo frustração com a interface. Isso não significa substituir a atividade criativa nem garantir domínio sem prática: o exemplo de competência mantém aprender, dominar ferramentas e superar desafios de design como parte da experiência. A orientação procura remover impedimentos indevidos do instrumento e apoiar a [[apropriação das ferramentas]], preservando espaço para desenvolvimento de habilidade e realização.',[11,13],['5.2 Radiant Pattern Example','Competence','Intuitive Design and Clear Feedback']);

direct('Quando desbloqueios opcionais por participação podem se alinhar a World Creation, e qual fronteira o artigo estabelece em relação ao grind?',
'O artigo admite recompensar participação em diferentes aspectos do jogo com [[qualidades cosméticas opcionais, peças aprimoradas ou elementos temáticos]], desde que essa participação não gire apenas em torno de grind. Recursos fundamentais devem continuar prontamente disponíveis. A proposta preserva objetivos de progressão e a possibilidade de adquirir novas oportunidades criativas sem restringir a criatividade necessária. Portanto, desbloquear algo não é automaticamente uma falha do padrão: a análise depende de [[opcionalidade, centralidade da ferramenta e forma de obtenção]]. O texto apresenta essa possibilidade como adequação ao modelo, sem demonstrar seu impacto psicológico ou comercial.',[13],['5.2 Radiant Pattern Example','Optional Unlocks By Engaging Play']);

direct('O que LittleBigPlanet, Super Mario Maker e Dreams ilustram no campo Good Examples, e o que essa exemplificação não permite concluir sobre cada jogo inteiro?',
'O artigo usa [[Create Mode de LittleBigPlanet]] para ilustrar criação de fases e publicação à comunidade; [[Super Mario Maker]] para criação com itens e recursos da franquia; e [[Dreams]] para criação de jogos e experiências, inclusive visuais e musicais. Eles tornam a mecânica e suas possibilidades mais compreensíveis ao desenvolvedor. O campo exemplifica aplicações de World Creation, não constitui auditoria completa de todos os sistemas desses títulos nem comprovação de efeitos sobre o bem-estar. O próprio trabalho registra que ainda não houve avaliações com jogadores para validar efeitos diretos dos padrões.',[10,13,16],['5.1 Radiant Pattern Structure','Good Examples','5.2 Radiant Pattern Example','6.5 Study Limitations']);

direct('Por que a avaliação de uma mecânica radiant precisa enfrentar confundimento com som, gráficos e narrativa, segundo Operationalizing?',
'Os padrões precisam estar inseridos no [[contexto de um jogo para afetar diretamente o gameplay]], mas uma experiência completa inclui elementos visuais, sonoros, gráficos e narrativos. Por isso, torna-se difícil determinar o que decorre do padrão e o que resulta do conjunto da experiência. O artigo pede métricas capazes de focalizar padrões isoladamente e convida academia e indústria a investigar metodologias que distingam essas contribuições. A limitação não é resolvida simplesmente ao observar satisfação geral ou motivação: é necessário enfrentar a [[atribuição dos efeitos]], questão ainda aberta no estudo e relevante para a precisão da avaliação.',[15,16],['6.3 The Challenge to Evaluate Players Well-Being','6.5 Study Limitations']);

direct('Que uso de PENS e Intrinsic Motivation Inventory é sugerido em Operationalizing, e por que esses instrumentos não são apresentados como avaliação direta e conclusiva do bem-estar causado por um padrão?',
'O artigo afirma que é possível avaliar [[aspectos da motivação intrínseca e necessidades de autonomia, competência e vínculo]], mencionando PENS e Intrinsic Motivation Inventory como instrumentos. Ao mesmo tempo, reconhece que ainda não há metodologia para avaliar diretamente o bem-estar causado pelos padrões e questiona como separar a contribuição da mecânica daquela de todo o jogo. Portanto, os instrumentos oferecem caminhos para examinar construtos relevantes, e não uma prova automática de causalidade ou um índice total do bem-estar. A questão metodológica permanece: [[qual parcela da experiência decorre do padrão analisado?]]',[15],['6.3 The Challenge to Evaluate Players Well-Being']);

direct('Como Operationalizing separa evidências de conscientização ética de evidências sobre efeitos reais dos Radiant Patterns no bem-estar?',
'A seção de avaliação relata que trabalho anterior mostrou capacidade de [[aumentar a consciência sobre preceitos éticos]] por meio de padrões radiantes. Porém, afirma que os efeitos reais sobre bem-estar ainda não puderam ser investigados, pois a mecânica deve operar em um jogo com muitos outros componentes que também influenciam a experiência. O artigo exige metodologias e medidas específicas para avançar nessa análise. Assim, aprender a reconhecer ou discutir ética constitui um resultado diferente de demonstrar [[mudança de bem-estar atribuível a uma implementação]], e não deve ser usado como substituto dessa evidência.',[15,16],['6.3 The Challenge to Evaluate Players Well-Being','6.5 Study Limitations']);

direct('Por que a resposta de jogadores a um padrão pode variar mesmo quando ele foi projetado para ser positivo, segundo as limitações de Operationalizing?',
'O texto reconhece que [[interpretação e perfil do jogador]] afetam a experiência e que não se pode confiar que os padrões funcionem em todo contexto previsto. Experiência de jogo, exposição anterior, consciência das consequências e familiaridade com SDT podem alterar sua compreensão. Alguns jogadores podem preferir práticas apesar de possíveis consequências negativas; outros podem evitar um jogo ao saber de sua presença. Esses contrastes reforçam a necessidade de avaliações com perfis diversos. A intenção preventiva e o enquadramento teórico oferecem critérios de projeto, mas não autorizam prever uma [[resposta uniforme ou universalmente benéfica]].',[14,16],['6.1 Players Perception on Radiant Patterns','6.5 Study Limitations']);

direct('Qual conflito de adoção o artigo identifica entre padrões enganosos rentáveis e alternativas radiantes, e que investigação econômica ainda propõe?',
'A discussão observa que padrões enganosos são [[estratégias estabelecidas, difundidas e rentáveis]], podendo ser usados mesmo quando desenvolvedores reconhecem seu potencial de dano. Para ampliar a aceitação de alternativas, o artigo propõe explorar como padrões radiantes podem gerar retorno à indústria e se tornar mais atraentes. Essa é uma agenda, não um resultado: o trabalho declara que a viabilidade comercial concreta ainda não foi demonstrada e que não há garantia de retorno imediato em engajamento ou desempenho financeiro. Portanto, [[valor ético e retorno comercial]] devem ser distinguidos, sem usar rentabilidade de práticas enganosas como justificativa para mantê-las.',[15,16],['6.4 A Radiant Pattern Repository','6.5 Study Limitations']);

direct('Como o repositório aberto imaginado em Operationalizing depende da contribuição de jogadores, pesquisadores e desenvolvedores, e qual é a função do template nesse processo?',
'O artigo propõe identificar padrões a partir das [[experiências de jogadores e pesquisadores com mecânicas]], sistematizando criação e documentação pelo template. Comunidade de IHC e desenvolvedores poderiam colaborar na identificação e no refinamento, formando um repositório aberto de padrões orientado por princípios éticos. Nesse processo, a estrutura comum organiza descrições e facilita compartilhar alternativas. A proposta não equivale a declarar que um repositório tenha validado os efeitos dos padrões ou garantido sua adoção. Seu papel é fornecer [[infraestrutura conceitual e documental para colaboração]], enquanto avaliação com jogadores e retorno comercial permanecem limitações explícitas.',[9,16],['5.1 Radiant Pattern Structure','6.4 A Radiant Pattern Repository','6.5 Study Limitations']);

direct('Que relação Operationalizing estabelece entre um template padronizado, comunicação clara e comparação entre padrões diferentes?',
'O artigo exige que [[cada padrão identificado siga a mesma estrutura documental]]. Um formato padronizado pretende facilitar comunicação clara, permitir comparação entre padrões e sustentar um repositório compartilhável e robusto. A utilidade dessa padronização está em tornar explícitos elementos comparáveis: problema, contexto, solução, necessidades, riscos, implementações e exemplos. Isso não torna as implementações idênticas nem elimina diferenças de contexto. Ao contrário, a estrutura dá um lugar para registrar essas diferenças, possibilitando discutir alternativas com [[critérios e vocabulário comuns]], sem confundir consistência documental com comprovação empírica de eficácia.',[8,9,10],['5.1 Radiant Pattern Structure']);

synthesis('Como articular a prevenção de riscos em Operationalizing com a responsabilidade do prestador e a avaliação documentada de riscos em Safety by Design?',
'Como [[síntese analítica]], os trabalhos aproximam prevenção e decisões de projeto, mas atuam em escalas diferentes. Operationalizing pede minimizar riscos psicológicos previsíveis e explicitar aplicações problemáticas em Watch For; Safety by Design afirma que o ônus da segurança não deve recair apenas no usuário e solicita avaliações documentadas de riscos e impactos. O template pode tornar discutíveis riscos de uma mecânica, enquanto responsabilidades e fluxos organizacionais sustentam sua análise ao longo do serviço. Essa articulação não torna as categorias equivalentes: [[não diminuir necessidades SDT não cobre todo risco de segurança]], e exemplos e princípios não demonstram eficácia por si só.',[6,10],['4 Revisiting and Reshaping Game Radiant Patterns','5.1 Radiant Pattern Structure'],['sbd',[22,27],['Principle 1','Principle 1.6']]);

synthesis('Como comparar o acesso às ferramentas de World Creation com autonomia e proteção por padrão em Safety by Design sem confundir liberdade criativa e segurança?',
'World Creation procura preservar [[controle sobre a criação e acesso ao núcleo de ferramentas]], evitando que pagamento ou grind excessivo restrinjam expressão. Safety by Design recomenda ferramentas para gerir segurança, configurações protetoras por padrão e oportunidade de revisar escolhas. A conexão analítica é perguntar se o serviço oferece meios efetivos para exercer controle, em vez de apenas declarar liberdade. As finalidades específicas diferem: acesso criativo não substitui privacidade, bloqueio ou denúncia; proteção não deve ser interpretada como licença para retirar toda agência. A comparação exige examinar [[que decisão o usuário pode realmente tomar e em que condições]], sem inferir resultados conjuntos demonstrados.',[11,12],['5.2 Radiant Pattern Example'],['sbd',[30],['Principle 2','Principle 2.1']]);

synthesis('O que o problema de atribuir bem-estar a um padrão em Operationalizing acrescenta à exigência de métricas significativas e accountability de Safety by Design?',
'Safety by Design diferencia estatísticas de escala de denúncias de [[análise da eficácia de regras e moderação]]. Operationalizing, por sua vez, questiona o que resulta do padrão e o que decorre do conjunto de elementos do jogo, mencionando medidas de necessidades e motivação. A ponte analítica é exigir indicadores alinhados à pergunta de avaliação: contar ações ou observar satisfação geral não responde automaticamente se uma intervenção produziu o efeito pretendido. Os objetos são diferentes, moderação de serviço e mecânica de jogo, mas ambos tornam relevante [[explicitar o que cada medida sustenta e o que não permite concluir]]. Não se afirma que os trabalhos tenham validado um mesmo protocolo.',[15,16],['6.3 The Challenge to Evaluate Players Well-Being','6.5 Study Limitations'],['sbd',[36],['Principle 3.4']]);

synthesis('Como o critério de World Creation sobre grind e pagamento ajuda a discutir as funcionalidades de uso prolongado listadas no documento local do Art. 48?',
'O documento local enumera funcionalidades que incentivam atividade prolongada, como [[recompensas variáveis, gamificação, notificações e ofertas limitadas]]. Operationalizing examina mais especificamente quando o núcleo criativo, salvamento e compartilhamento são condicionados a pagamento ou grind excessivo. A correlação permite perguntar qual função está bloqueada, que pressão é criada e como autonomia e competência podem ser afetadas. Ela não autoriza declarar que toda gamificação seja enganosa ou que todo tempo prolongado prejudique bem-estar. [[Fator considerado para classificação e critério de design psicológico não são o mesmo diagnóstico]]; o texto de Art. 48 é tratado como documento local, sem afirmação de vigência.',[12,13],['5.2 Radiant Pattern Example','Watch For'],['art',[4],['Art. 48, §10, XVIII–XX e XXII']]);

synthesis('Por que os critérios de curadoria, controles parentais e moderação do Art. 48 não bastam para concluir que uma implementação de World Creation é radiant?',
'No documento local, [[controle editorial, curadoria, controles etários/parentais e políticas de moderação]] entram na atribuição da classificação, com especificações remetidas aos Guias. Operationalizing pede analisar problema, contexto, solução e efeitos sobre cada necessidade; World Creation inclui acesso a ferramentas, aprendizado e conexão por compartilhamento. A síntese distingue avaliação de características da plataforma de análise situada da mecânica. Um serviço pode precisar moderar criações e, ainda assim, ter ferramentas que frustrem competência ou cobrem pelo núcleo criativo. Inversamente, oferecer expressão não resolve toda segurança de conteúdo. A correlação é analítica, [[sem afirmar vigência legal nem equivalência entre classificação e radiância]].',[9,10,12],['5.1 Radiant Pattern Structure','5.2 Radiant Pattern Example'],['art',[4,5],['Art. 48, §§14–15']]);

synthesis('Como o cenário especulativo de Ouroboros Seed permite problematizar a aparência de progresso e comunidade à luz dos critérios de World Creation?',
'No [[cenário ficcional]] de Games Made Elsewhere, a promessa de controle, progresso e comunidade é seguida por crises personalizadas, grind e Pay-to-Skip, com exploração de vulnerabilidades de Helena. World Creation justifica apoio a autonomia, competência e vínculo por controle criativo, domínio de ferramentas e compartilhamento, enquanto adverte contra dependência financeira ou grind excessivo do núcleo. A comparação analítica mostra por que aparência de comunidade ou progresso não garante suporte às necessidades: é necessário examinar [[como o sistema funciona e que condições impõe]]. Não se trata de aplicar um teste empírico ao jogo real: Ouroboros Seed é uma provocação especulativa, e o artigo de padrões não demonstrou eficácia direta.',[11,12,16],['5.2 Radiant Pattern Example','6.5 Study Limitations'],['chip',[2],['3 A Speculative Perspective: Helena and The Gilded Cage of Ouroboros Seed']]);

synthesis('Que tensão surge ao relacionar perfis de jogadores em Operationalizing ao creator-consumer divide de Games Made Elsewhere?',
'Operationalizing reconhece que [[experiência, letramento, exposição anterior e perfis pessoais]] alteram a percepção dos padrões. Games Made Elsewhere propõe uma lente estrutural: diferenças entre contextos de criação e consumo, precariedade, letramento e arbitragem regulatória podem ampliar vulnerabilidades. A ponte analítica exige que avaliar perfis não se limite a preferência individual, ignorando condições sociais e poder. Ao mesmo tempo, o argumento especulativo não fornece medidas empíricas dos efeitos de cada padrão. Assim, a correlação orienta perguntas sobre [[validade contextual e participação das comunidades]], sem declarar que os dois trabalhos comprovaram um mesmo mecanismo causal ou que todos os jogadores de uma região respondam igualmente.',[14,16],['6.1 Players Perception on Radiant Patterns','6.5 Study Limitations'],['chip',[1,2,3],['2 The Creator-Consumer Divide as a Lens for Understanding Systemic Player Vulnerability','4 Toward a Decolonial Game and Play Research']]);

synthesis('Como o template de Operationalizing pode informar as ferramentas de apoio ao desenvolvedor propostas em From Understanding to Intervention, e o que ainda precisaria ser testado?',
'O template documenta [[problema, contexto, solução, necessidades, riscos e exemplos que falham ou correspondem aos critérios]]. A agenda propõe ferramentas integradas a engines para identificar decisões potencialmente problemáticas e sugerir alternativas éticas, respeitando contexto e objetivos do desenvolvimento. Como síntese, descrições estruturadas poderiam fornecer conteúdo argumentado para essas sugestões, em vez de avisos triviais ou regras descontextualizadas. Mas preencher um template não produz automaticamente uma ferramenta inteligente, útil ou adotada. A agenda exige testes empíricos e reconhece rejeição quando ferramentas parecem limitar criatividade ou objetivos financeiros. [[Integração e eficácia permanecem propostas a investigar]], não resultados demonstrados pela comparação.',[8,9,10],['5 Crafting Radiance: A Guide to Propose Radiant Patterns','5.1 Radiant Pattern Structure'],['agenda',[9,10],['3.2 Development of Software Artifacts to Foster Real-Time Awareness on Users and Developers']]);

synthesis('Como a limitação de viabilidade comercial em Operationalizing se relaciona às restrições organizacionais discutidas na agenda de intervenção?',
'Operationalizing declara que [[retorno comercial concreto dos padrões radiantes ainda não foi demonstrado]] e propõe investigar como torná-los atraentes à indústria. A agenda acrescenta que decisões de monetização frequentemente cabem a acionistas, executivos e equipes de produto, orientados por KPIs, podendo deixar designers com pouca autonomia para rejeitar práticas manipulativas. A síntese impede reduzir adoção a ensinar uma alternativa ao desenvolvedor: é preciso entender quem decide, sob quais metas e restrições. Isso não justifica práticas nocivas nem prova que padrões radiantes sejam inviáveis. Delimita [[questões econômicas e distribuição de poder decisório]] que a pesquisa precisa investigar antes de prometer adoção.',[15,16],['6.4 A Radiant Pattern Repository','6.5 Study Limitations'],['agenda',[10],['3.2 Development of Software Artifacts to Foster Real-Time Awareness on Users and Developers']]);

synthesis('Como combinar a discussão de PENS/IMI em Operationalizing com a agenda de métodos para autonomia, justiça, transparência e manipulação percebida?',
'Operationalizing aponta [[PENS e IMI]] como caminhos para aspectos de necessidades e motivação, mas destaca confundimento entre padrão e experiência total do jogo. A agenda propõe adaptar questionários e métricas comportamentais para autonomia percebida, justiça, transparência, respeito, manipulação e bem-estar, articulando telemetria e dados qualitativos. A relação analítica é ampliar e alinhar medidas à pergunta: suporte a necessidades, percepção de manipulação e engajamento não são indicadores intercambiáveis. Também é preciso investigar efeitos da intervenção e diferenças de gênero/modelo de monetização. Os textos oferecem [[direções metodológicas complementares]], sem fornecer um protocolo único já validado que isole causalmente o efeito de qualquer padrão.',[15,16],['6.3 The Challenge to Evaluate Players Well-Being','6.5 Study Limitations'],['agenda',[10,11],['3.3 Advancing Methods and Measures for Assessing Dark Pattern Prevalence and Player Experience, Including Well-Being']]);

synthesis('Como a passagem de World Creation a Creative Suite e a adoção de níveis e variantes em Beyond Dark Patterns respondem a limites de contexto do template de Operationalizing?',
'Operationalizing já exige [[contexto recomendado, solução e análise individual das necessidades]], mas exemplifica World Creation de maneira ampla. No estudo posterior, participantes observam que criação de cenários e customização de algo existente têm particularidades; World Creation passa a Creative Suite, abrangendo diferentes experiências criativas. O framework incorpora níveis progressivos e variantes ambientais para adaptar a implementação sem perder lógica central. A síntese identifica um refinamento de precisão e escopo, não a refutação do compromisso ético anterior. [[Níveis são base metodológica, não experiência universal]], e ocorrência em jogos ou discussão especializada não demonstra, sozinha, eficácia longitudinal ou uso validado em produção.',[9,10,11],['5.1 Radiant Pattern Structure','5.2 Radiant Pattern Example'],['hci',[8,10,11,15],['4.1 Baseline Radiant Patterns Required Structural Refinement','4.2 Refined RPs Framework Established a Shared Lexicon','6 Discussion: Radiant Patterns and Industry Practice']]);

synthesis('Que elementos a governança do catálogo em Beyond Dark Patterns acrescenta à proposta de repositório aberto de Operationalizing?',
'Operationalizing imagina [[colaboração para identificar, refinar e documentar padrões]] a partir de experiências de jogadores e pesquisadores. Beyond Dark Patterns especifica contribuições estruturadas ou baseadas em problemas, distinção visível entre candidatos e padrões finalizados, avaliação por especialistas e devolução para refinamento iterativo. Essa articulação transforma abertura em uma questão de processo: quem contribui, o que é verificado e como se comunica maturidade. O estudo posterior também reconhece riscos de seleção e expertise desigual. A síntese distingue [[padronização documental, verificação comunitária e evidência de efeito em jogadores]]; organizar um catálogo não demonstra automaticamente eficácia, consenso global ou validação longitudinal.',[9,16],['5.1 Radiant Pattern Structure','6.4 A Radiant Pattern Repository'],['hci',[13,15,16],['5 A Catalog of Games Radiant Patterns','6 Discussion: Radiant Patterns and Industry Practice','7 Final Remarks']]);

synthesis('Por que encontrar uma mecânica em jogos comerciais e documentá-la pelo template não basta para demonstrar um Radiant Pattern eficaz, considerando Operationalizing e Beyond Dark Patterns?',
'Operationalizing usa exemplos para [[tornar a proposta operacional e compreensível]], mas reconhece ausência de avaliações com jogadores sobre efeitos diretos. Beyond Dark Patterns acrescenta que uma instância autoetnográfica não confirma um padrão: são necessárias recorrência, discussão e coerência com os componentes do framework; observações podem gerar falsos positivos. A comparação separa quatro passos: observar uma implementação, descrevê-la, verificar sua identidade/recorrência e avaliar efeitos. Eles são relacionados, mas não equivalentes. [[Presença em um título comercial não valida o framework em desenvolvimento ativo nem prova bem-estar]], especialmente sem dados longitudinais e com os limites de atribuição explicitados pelos textos.',[10,13,16],['5.2 Radiant Pattern Example','6.5 Study Limitations'],['hci',[11,15,16],['4.3 Eliciting RPs from Play Experiences with Commercial Games','6 Discussion: Radiant Patterns and Industry Practice','7 Final Remarks']]);

synthesis('Que relação pode ser construída entre Untranslation/termos inacessíveis no Interact e os problemas de ferramentas opacas e letramento em Operationalizing?',
'O Interact descreve [[termos ou políticas em outro idioma]] e acesso deslocado a páginas externas como casos que criam barreiras à informação. Operationalizing explica que ferramentas mal documentadas e opacas podem limitar a realização de ideias, prejudicando competência e autonomia, e reconhece variação de letramento e percepção. A ponte analítica é analisar condições concretas de compreensão e ação, em vez de assumir que oferecer texto ou ferramenta produz controle efetivo. Os objetos diferem: políticas em apps e instrumentos criativos em jogos. Portanto, [[não se transfere automaticamente a taxonomia ou a prevalência dos aplicativos para jogos]], nem se afirma efeito causal de bem-estar medido pelos dois estudos.',[12,14],['5.2 Radiant Pattern Example','Poor implementations or Obfuscated Tools','6.1 Players Perception on Radiant Patterns'],['interact',[6,8],['3 Results','5 Limitations']]);

synthesis('Como distinguir Ad-locked Rewards e Task-based Rewards do Interact dos desbloqueios opcionais compatíveis com World Creation, sem classificar toda recompensa como manipulativa?',
'O Interact descreve [[Ad-locked Rewards]] como exigir assistir a anúncio para receber benefício e Task-based Rewards como missões fora do fluxo principal que recompensam com aspectos do serviço. Em World Creation, recursos centrais devem ser acessíveis, mas recompensas cosméticas ou temáticas opcionais por participação variada podem caber no modelo, sem depender apenas de grind. A comparação exige examinar [[o que é condicionado, a função no fluxo e a pressão exercida]], em vez de tratar a palavra recompensa como diagnóstico. Não se conclui que as classificações de apps determinem radiância em jogos: o corpus e a observação inicial de dez minutos também limitam o alcance empírico do Interact.',[12,13],['5.2 Radiant Pattern Example','Watch For','Optional Unlocks By Engaging Play'],['interact',[6,8],['3 Results','5 Limitations']]);

synthesis('Como articular responsabilidade organizacional, documentação de mecânicas e avaliação de impacto em uma resposta a danos, a partir de Safety by Design, Operationalizing e da agenda de intervenção?',
'Como [[síntese para arguição]], Safety by Design distribui responsabilidades e exige avaliar riscos previstos; Operationalizing torna explícitos contexto, necessidades, falhas e alternativas de uma mecânica; a agenda pede medidas de impacto e examina limites de decisão de designers diante de KPIs e gestão. Essa combinação permite perguntar quem responde, o que a proposta modifica e como saber se funciona. Nenhuma camada resolve as demais: um template não cria autoridade organizacional, um responsável nomeado não comprova efeito e uma métrica isolada não explica todo bem-estar. Os textos sustentam [[perguntas complementares de governança, design e evidência]], sem oferecer uma solução integrada já testada ou universal.',[6,10,15,16],['4 Revisiting and Reshaping Game Radiant Patterns','5.1 Radiant Pattern Structure','6.3 The Challenge to Evaluate Players Well-Being','6.5 Study Limitations'],['sbd',[22,27],['Principle 1','Principle 1.6']],['agenda',[10,11],['3.2 Development of Software Artifacts to Foster Real-Time Awareness on Users and Developers','3.3 Advancing Methods and Measures for Assessing Dark Pattern Prevalence and Player Experience, Including Well-Being']]);

if(cards.length !== 50 || new Set(cards.map(card=>card.id)).size !== 50) throw Error(`Contagem inválida ${cards.length}`);
const previous = await read('src/data/cards.json');
for(const card of cards) {
  if(previous.some(old=>old.id === card.id || old.question === card.question)) throw Error(`ID/pergunta já existente ${card.id}`);
  for(const reference of [{articleId:card.articleId,source:card.source},...(card.relatedSources??[])]) {
    const doc=documents.get(reference.articleId);
    if(reference.source.title !== doc.title || reference.source.file !== doc.file) throw Error(`Referência incorreta ${card.id}`);
    for(const evidence of reference.source.evidence) if(!doc.pages.some(page=>reference.source.pages.includes(page.page)&&page.text.includes(evidence))) throw Error(`Evidência inválida ${card.id}`);
  }
}
await fs.writeFile(path.join(here,`${ids.rp}.json`),JSON.stringify(cards,null,2)+'\n','utf8');
console.log(`${cards.length} candidatos: ${cards.filter(card=>card.kind==='direct').length} diretos, ${cards.filter(card=>card.kind==='synthesis').length} sínteses; IDs, títulos, SHA-256 e evidências conferidos. Não publicados nem aprovados.`);
